import json, sys, time, urllib.request, urllib.error
BASE = "http://localhost:8080"
token = None
log = {"retries": {}, "token_refreshes": 0}

def get_token():
    global token
    while True:
        try:
            req = urllib.request.Request(BASE + "/token", method="POST", data=b"")
            with urllib.request.urlopen(req, timeout=30) as r:
                token = json.load(r)["token"]; log["token_refreshes"] += 1; return
        except urllib.error.HTTPError as e:
            handle_wait(e, "/token")

def handle_wait(e, path):
    log["retries"].setdefault(f"{e.code}", 0); log["retries"][f"{e.code}"] += 1
    ra = e.headers.get("Retry-After")
    body = e.read()[:200]
    print(f"{path}: HTTP {e.code} retry-after={ra} body={body!r}", file=sys.stderr)
    time.sleep(float(ra) if ra else 1.0)

def get(path):
    for attempt in range(200):
        if token is None: get_token()
        req = urllib.request.Request(BASE + path, headers={"Authorization": f"Bearer {token}"})
        try:
            with urllib.request.urlopen(req, timeout=30) as r:
                return r.status, json.load(r)
        except urllib.error.HTTPError as e:
            if e.code == 401:
                print(f"{path}: 401, refreshing token", file=sys.stderr)
                get_token(); continue
            if e.code == 404:
                return 404, None
            handle_wait(e, path)
        except (urllib.error.URLError, json.JSONDecodeError, ConnectionError, TimeoutError) as e:
            print(f"{path}: {e!r}", file=sys.stderr); time.sleep(1)
    raise RuntimeError(f"gave up on {path}")

pages = []
path = "/orders?page=1"
while path:
    st, d = get(path)
    assert st == 200, (path, st)
    pages.append(d)
    print(f"page {d['page']}/{d['total_pages']} items={len(d['items'])} next={d['next']}", file=sys.stderr)
    path = d["next"]
cust_ids = sorted({o["customer_id"] for p in pages for o in p["items"]})
customers = {}
for cid in cust_ids:
    st, d = get(f"/customers/{cid}")
    customers[cid] = d
json.dump({"pages": pages, "customers": customers, "log": log}, open("/tmp/recon/raw.json", "w"))
print(json.dumps(log), file=sys.stderr)
EOF
